1	//! Bounded topology acquisition shared by the DRM adapter and fault fixtures.
2	use super::{Failure, Stage};
3	use crate::output::{self, Connector, Encoder, Format, Plane, Topology};
4	use smithay::{
5	    backend::drm::DrmDevice,
6	    reexports::drm::control::{self, Device as _, ModeFlags, ModeTypeFlags},
7	};
8	use std::collections::{BTreeMap, BTreeSet};
9	
10	#[derive(Clone, Debug, PartialEq, Eq)]
11	struct Resources {
12	    connectors: Vec<u32>,
13	    encoders: Vec<u32>,
14	    crtcs: Vec<u32>,
15	}
16	struct ConnectorRecord<M> {
17	    connector: Connector,
18	    modes: Vec<M>,
19	}
20	trait Query {
21	    type Mode;
22	    fn resources(&mut self) -> Result<Resources, Failure>;
23	    fn connector(&mut self, id: u32) -> Result<ConnectorRecord<Self::Mode>, Failure>;
24	    fn encoder(&mut self, id: u32) -> Result<Encoder, Failure>;
25	    fn primary_planes(&mut self, crtc: u32) -> Result<Vec<(u32, Vec<Format>)>, Failure>;
26	}
27	pub(super) struct Inventory<M = control::Mode> {
28	    pub topology: Topology,
29	    /// Original kernel modes, indexed by the selected connector/mode_index.
30	    /// Retained privately; a future commit must revalidate this generation.
31	    pub modes: BTreeMap<u32, Vec<M>>,
32	}
33	fn invalid() -> Failure {
34	    Failure::at(Stage::OutputTopology)
35	}
36	fn io(error: std::io::Error) -> Failure {
37	    Failure {
38	        stage: Stage::OutputDiscovery,
39	        errno: error.raw_os_error(),
40	    }
41	}
42	fn ids(values: &[u32], cap: usize) -> Result<BTreeSet<u32>, Failure> {
43	    if values.len() > cap {
44	        return Err(invalid());
45	    }
46	    let result: BTreeSet<_> = values.iter().copied().collect();
47	    if result.len() != values.len() || result.contains(&0) {
48	        return Err(invalid());
49	    }
50	    Ok(result)
51	}
52	fn validate(resources: &Resources) -> Result<(), Failure> {
53	    ids(&resources.connectors, output::MAX_CONNECTORS)?;
54	    ids(&resources.encoders, output::MAX_ENCODERS)?;
55	    ids(&resources.crtcs, output::MAX_CRTCS)?;
56	    Ok(())
57	}
58	fn same_resources(a: &Resources, b: &Resources) -> bool {
59	    let ordered = |values: &[u32]| values.iter().copied().collect::<BTreeSet<_>>();
60	    ordered(&a.connectors) == ordered(&b.connectors)
61	        && ordered(&a.encoders) == ordered(&b.encoders)
62	        && ordered(&a.crtcs) == ordered(&b.crtcs)
63	}
64	fn acquire<Q: Query>(
65	    query: &mut Q,
66	    render_formats: Vec<Format>,
67	) -> Result<Inventory<Q::Mode>, Failure> {
68	    let resources = query.resources()?;
69	    validate(&resources)?;
70	    if render_formats.len() > output::MAX_FORMATS {
71	        return Err(invalid());
72	    }
73	    let mut topology = Topology {
74	        crtcs: resources.crtcs.clone(),
75	        render_formats,
76	        ..Topology::default()
77	    };
78	    let mut modes = BTreeMap::new();
79	    for id in &resources.connectors {
80	        let record = query.connector(*id)?;
81	        if record.connector.id != *id
82	            || record.connector.modes.len() != record.modes.len()
83	            || record.modes.len() > output::MAX_MODES
84	        {
85	            return Err(invalid());
86	        }
87	        modes.insert(*id, record.modes);
88	        topology.connectors.push(record.connector);
89	    }
90	    for id in &resources.encoders {
91	        let encoder = query.encoder(*id)?;
92	        if encoder.id != *id {
93	            return Err(invalid());
94	        }
95	        topology.encoders.push(encoder);
96	    }
97	    let mut planes: BTreeMap<u32, Plane> = BTreeMap::new();
98	    for crtc in &resources.crtcs {
99	        let records = query.primary_planes(*crtc)?;
100	        if records.len() > output::MAX_PLANES {
101	            return Err(invalid());
102	        }
103	        let mut seen = BTreeSet::new();
104	        for (id, mut formats) in records {
105	            if id == 0 || !seen.insert(id) || formats.len() > output::MAX_FORMATS {
106	                return Err(invalid());
107	            }
108	            formats.sort();
109	            formats.dedup();
110	            if let Some(existing) = planes.get_mut(&id) {
111	                if existing.formats != formats {
112	                    return Err(invalid());
113	                }
114	                existing.crtcs.push(*crtc);
115	            } else {
116	                if planes.len() == output::MAX_PLANES {
117	                    return Err(invalid());
118	                }
119	                planes.insert(
120	                    id,
121	                    Plane {
122	                        id,
123	                        crtcs: vec![*crtc],
124	                        formats,
125	                    },
126	                );
127	            }
128	        }
129	    }
130	    topology.planes = planes.into_values().collect();
131	    let after = query.resources()?;
132	    validate(&after)?;
133	    if !same_resources(&resources, &after) {
134	        return Err(invalid());
135	    }
136	    // Validate every reference even for disconnected/non-desktop connectors.
137	    output::plan(&topology).map_err(|_| invalid())?;
138	    Ok(Inventory { topology, modes })
139	}
140	struct DrmQuery<'a> {
141	    drm: &'a DrmDevice,
142	    resources: control::ResourceHandles,
143	    first: bool,
144	}
145	impl Query for DrmQuery<'_> {
146	    type Mode = control::Mode;
147	    fn resources(&mut self) -> Result<Resources, Failure> {
148	        let resources = if self.first {
149	            self.first = false;
150	            self.resources.clone()
151	        } else {
152	            self.drm.resource_handles().map_err(io)?
153	        };
154	        Ok(Resources {
155	            connectors: resources
156	                .connectors()
157	                .iter()
158	                .map(|id| u32::from(*id))
159	                .collect(),
160	            encoders: resources
161	                .encoders()
162	                .iter()
163	                .map(|id| u32::from(*id))
164	                .collect(),
165	            crtcs: resources.crtcs().iter().map(|id| u32::from(*id)).collect(),
166	        })
167	    }
168	    fn connector(&mut self, id: u32) -> Result<ConnectorRecord<Self::Mode>, Failure> {
169	        let handle = control::from_u32(id).ok_or_else(invalid)?;
170	        // Startup, explicit device change and resume are the only callers.
171	        let info = self.drm.get_connector(handle, true).map_err(io)?;
172	        let properties = self.drm.get_properties(handle).map_err(io)?;
173	        if properties.as_props_and_values().0.len() > 256 {
174	            return Err(invalid());
175	        }
176	        let mut non_desktop = false;
177	        for (property, value) in properties {
178	            let info = self.drm.get_property(property).map_err(io)?;
179	            if info.name().to_bytes() == b"non-desktop" {
180	                non_desktop = info
181	                    .value_type()
182	                    .convert_value(value)
183	                    .as_boolean()
184	                    .ok_or_else(invalid)?;
185	            }
186	        }
187	        if info.modes().len() > output::MAX_MODES || info.encoders().len() > output::MAX_ENCODERS {
188	            return Err(invalid());
189	        }
190	        let modes = info.modes().to_vec();
191	        let connection = match info.state() {
192	            control::connector::State::Connected => output::Connection::Connected,
193	            control::connector::State::Disconnected => output::Connection::Disconnected,
194	            control::connector::State::Unknown => output::Connection::Unknown,
195	        };
196	        Ok(ConnectorRecord {
197	            connector: Connector {
198	                id,
199	                connection,
200	                non_desktop,
201	                encoders: info.encoders().iter().map(|id| u32::from(*id)).collect(),
202	                current_encoder: info.current_encoder().map(u32::from),
203	                modes: modes
204	                    .iter()
205	                    .map(|mode| {
206	                        let (width, height) = mode.size();
207	                        let (hsync_start, hsync_end, htotal) = mode.hsync();
208	                        let (vsync_start, vsync_end, vtotal) = mode.vsync();
209	                        output::Mode {
210	                            width,
211	                            height,
212	                            hsync_start,
213	                            hsync_end,
214	                            htotal,
215	                            vsync_start,
216	                            vsync_end,
217	                            vtotal,
218	                            clock_khz: mode.clock(),
219	                            vscan: mode.vscan(),
220	                            interlaced: mode.flags().contains(ModeFlags::INTERLACE),
221	                            double_scan: mode.flags().contains(ModeFlags::DBLSCAN),
222	                            preferred: mode.mode_type().contains(ModeTypeFlags::PREFERRED),
223	                        }
224	                    })
225	                    .collect(),
226	            },
227	            modes,
228	        })
229	    }
230	    fn encoder(&mut self, id: u32) -> Result<Encoder, Failure> {
231	        let info = self
232	            .drm
233	            .get_encoder(control::from_u32(id).ok_or_else(invalid)?)
234	            .map_err(io)?;
235	        Ok(Encoder {
236	            id,
237	            crtcs: self
238	                .resources
239	                .filter_crtcs(info.possible_crtcs())
240	                .into_iter()
241	                .map(u32::from)
242	                .collect(),
243	            current_crtc: info.crtc().map(u32::from),
244	        })
245	    }
246	    fn primary_planes(&mut self, crtc: u32) -> Result<Vec<(u32, Vec<Format>)>, Failure> {
247	        self.drm
248	            .planes(&control::from_u32(crtc).ok_or_else(invalid)?)
249	            .map_err(|_| Failure::at(Stage::OutputDiscovery))?
250	            .primary
251	            .into_iter()
252	            .map(|plane| {
253	                let formats: Vec<_> = plane
254	                    .formats
255	                    .iter()
256	                    .take(output::MAX_FORMATS + 1)
257	                    .map(|format| Format {
258	                        code: format.code as u32,
259	                        modifier: format.modifier.into(),
260	                    })
261	                    .collect();
262	                Ok((plane.handle.into(), formats))
263	            })
264	            .collect()
265	    }
266	}
