277	        Ok((plan, modes)) => PreparedOutputs {
278	            plan: Some(plan),
279	            failure: None,
280	            modes,
281	        },
282	        Err(failure) => PreparedOutputs {
283	            plan: None,
284	            failure: Some(failure),
285	            modes: BTreeMap::new(),
286	        },
287	    }
288	}
