    let mut formats = BTreeMap::new();
    for (id, p) in by_plane {
        let common: Vec<_> = p
            .formats
            .iter()
            .copied()
            .collect::<BTreeSet<_>>()
            .intersection(&render)
            .copied()
            .collect();
        if common.is_empty() {
            continue;
        }
        formats.insert(id, common);
        for crtc in &crtcs {
            if p.crtcs.contains(crtc) {
                graph.edge(rn[crtc].1, pn[&id].0);
            }
        }
