        let plane = *pn
            .iter()
            .find(|(_, nodes)| nodes.0 == plane_node)
            .expect("plane node")
            .0;
        result.assignments.push(Assignment {
            connector: id,
            encoder,
            crtc,
            primary_plane: plane,
            mode_index: *index,
            mode: *mode,
            refresh_millihz: *refresh,
            candidate_formats: formats[&plane].clone(),
        });
    }
    result.unassigned.sort_by_key(|u| u.connector);
    Ok(result)
}

